// MyFenrir Wiki — self-contained HTML served under /wiki (Pages Function).
// Base64 is byte-identical to the fenrir-wiki deploy kit wiki.html. Non-routed (_lib).
export const WIKI_HTML_B64 = "";

export function wikiResponse(): Response {
  const bin = atob(WIKI_HTML_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, {
    status: 200,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "public, max-age=300, s-maxage=3600",
      "x-content-type-options": "nosniff",
      "referrer-policy": "strict-origin-when-cross-origin",
    },
  });
}
